#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "atax.h"

void init_array(int m, int n, double A[38][42], double x[42]) {
    int i, j;
    double fn;
    fn = (double)n;

    for (i = 0; i < n; i++)
        x[i] = 1 + (i / fn);
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            A[i][j] = (double)((i + j) % n) / (5 * m);
}

